const FONT_IMPORT = `@import url('https://fonts.googleapis.com/css2?family=Lora:ital,wght@0,500;0,600;1,500&family=Inter:wght@400;500;600&family=JetBrains+Mono:wght@400;500&display=swap');`;

// Ingebouwde foto's voor de startproducten (base64, zodat geen los bestand nodig is).
// Nieuwe producten die je later toevoegt via /admin.html gebruiken een externe foto-URL.
const IMAGE_MAP = {
  "olv-1x75": "data:image/jpeg;base64,",
  "olv-3x75": "data:image/jpeg;base64,",
  "olv-6x75": "data:image/jpeg;base64,",
};

const HERO_IMAGE = "data:image/jpeg;base64,";

// Producten worden live opgehaald bij de backend (zie useEffect hieronder).
// Voeg nieuwe producten toe via /admin.html met een foto-URL (bv. via Google Foto's "delen"-link,
// of upload je foto's naar imgur.com en gebruik de directe link).
function mapProduct(row) {
  return {
    id: row.id,
    name: row.name,
    variant: row.variant,
    price: row.price_cents / 100,
    compareAt: row.compare_at_cents ? row.compare_at_cents / 100 : null,
    image: (row.image_path && row.image_path.startsWith("http")) ? row.image_path : (IMAGE_MAP[row.id] || null),
    desc: row.description || "",
  };
}

const REMOVED = ["Zink", "Minerale olie", "Vaseline", "Kleurstoffen", "Conserveermiddelen"];

function currency(n) {
  return new Intl.NumberFormat("nl-NL", { style: "currency", currency: "EUR" }).format(n);
}

